using PaymentService.Contracts;
using PaymentService.Domain;
namespace PaymentService.Application; public interface IPaymentRepository { Task<Payment> CreateAsync(Payment x, CancellationToken ct); Task<Payment?> GetAsync(Guid uid, CancellationToken ct); Task<bool> CancelAsync(Guid uid, CancellationToken ct); } public sealed class PaymentApplication(IPaymentRepository r) { public async Task<PaymentDto> CreateAsync(int p, CancellationToken ct) => Map(await r.CreateAsync(new(Guid.NewGuid(), PaymentStatus.PAID, p), ct)); public async Task<PaymentDto?> GetAsync(Guid u, CancellationToken ct) => await r.GetAsync(u, ct) is { } x ? Map(x) : null; public Task<bool> CancelAsync(Guid u, CancellationToken ct) => r.CancelAsync(u, ct); private static PaymentDto Map(Payment x) => new(x.PaymentUid, x.Status, x.Price); }
